/**
 * Reverse stealth conformance: the Raxol Elixir implementation is the source of
 * truth here. It proves a stealth payment Elixir GENERATES is byte-for-byte
 * reproducible by this reference AND discoverable + spendable by the receiver
 * side (checkViewTag / deriveStealthOwner). The forward fixture
 * (stealth_conformance_test.exs in raxol) proves the opposite direction.
 *
 * Fixture generated by
 * raxol/packages/raxol_payments/scripts/gen_reverse_stealth_vectors.exs;
 * regenerate it there if the Elixir derivation changes. Moved from the Xochi
 * widget unchanged.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { ethers } from "ethers";
import { describe, it, expect } from "vitest";
import {
  deriveStealthKeys,
  computeStealthAddress,
  checkViewTag,
  deriveStealthOwner,
  type StealthAnnouncement,
} from "@xochi/signer";

interface ReverseVector {
  name: string;
  signature: string;
  spending_priv: string;
  spending_pub: string;
  viewing_priv: string;
  viewing_pub: string;
  ephemeral_priv: string;
  stealth_address: string;
  ephemeral_pub: string;
  view_tag: number;
}

const vectors: ReverseVector[] = JSON.parse(
  readFileSync(
    join(dirname(fileURLToPath(import.meta.url)), "vectors", "reverse-stealth-vectors.json"),
    "utf8",
  ),
);

// A minimal announcement carrying only the fields the receiver checks use; the
// metadata is the view-tag byte alone.
function announcementFor(v: ReverseVector): StealthAnnouncement {
  return {
    schemeId: 1,
    stealthAddress: v.stealth_address,
    caller: "0x0000000000000000000000000000000000000000",
    ephemeralPubKey: v.ephemeral_pub,
    metadata: "0x" + v.view_tag.toString(16).padStart(2, "0"),
    blockNumber: 0,
    txHash: "0x",
    logIndex: 0,
  };
}

describe("reverse stealth conformance (Elixir -> TS)", () => {
  it("has vectors to check", () => {
    expect(vectors.length).toBeGreaterThan(0);
  });

  for (const v of vectors) {
    describe(v.name, () => {
      it("derive_keys reproduces the Elixir keys", () => {
        const k = deriveStealthKeys(v.signature);
        expect(ethers.hexlify(k.spendingKey)).toBe(v.spending_priv);
        expect(k.spendingPubKey).toBe(v.spending_pub);
        expect(ethers.hexlify(k.viewingKey)).toBe(v.viewing_priv);
        expect(k.viewingPubKey).toBe(v.viewing_pub);
      });

      it("computeStealthAddress reproduces the Elixir sender output", () => {
        const s = computeStealthAddress(
          { spendingPubKey: v.spending_pub, viewingPubKey: v.viewing_pub, chainId: 1 },
          ethers.getBytes(v.ephemeral_priv),
        );
        expect(s.stealthAddress.toLowerCase()).toBe(v.stealth_address.toLowerCase());
        expect(s.ephemeralPubKey).toBe(v.ephemeral_pub);
        expect(s.viewTag).toBe(v.view_tag);
      });

      it("receiver discovers the payment via the view tag", () => {
        const ann = announcementFor(v);
        expect(checkViewTag(ann, ethers.getBytes(v.viewing_priv))).toBe(true);
      });

      it("receiver derives the stealth owner EOA that controls the account", () => {
        const ann = announcementFor(v);
        const { stealthEOA } = deriveStealthOwner(
          ann,
          ethers.getBytes(v.spending_priv),
          ethers.getBytes(v.viewing_priv),
        );
        // The Elixir fixture's `stealth_address` is the stealth owner EOA
        // (address(P')). In the counterfactual SimpleAccount model this EOA is
        // the account owner; the announced destination is the counterfactual
        // account computed from it by an on-chain factory call, which the
        // caller (the widget's scanner) owns.
        expect(stealthEOA.toLowerCase()).toBe(v.stealth_address.toLowerCase());
      });
    });
  }
});
